package io.github.jesterportfolio.hearth.economy;

import java.util.*;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;

/** 화폐·수치·오프라인 처리는 콘텐츠의 개발 설정입니다. 운영 E1 결정을 대신하지 않습니다. */
public record EconomyContent(List<String> regions,Map<String,Good> goods,Map<Key,Long> demand,List<Facility> facilities,List<Route> routes,Map<String,Event> events,Policy policy,long tickMillis,String offline,int catchup,long fixtureBalance){
    public record Key(String region,String good) implements Comparable<Key>{public Key{key(region);key(good);}public int compareTo(Key other){return (region+"/"+good).compareTo(other.region+"/"+other.good);}}
    public record Good(String id,String material,long base,long target){public Good{key(id);if(material==null||!material.matches("[A-Z_]+")||base<1||base>1_000_000_000||target<1||target>1_000_000_000)throw new IllegalArgumentException("ECON_GOOD");}}
    public record Facility(String id,String region,String good,long capacity,Map<String,Long> inputs,int efficiency){public Facility{key(id);key(region);key(good);inputs=Map.copyOf(inputs);if(capacity<1||capacity>1_000_000||efficiency<0||efficiency>30000||inputs.values().stream().anyMatch(v->v<1||v>1000000))throw new IllegalArgumentException("ECON_FACILITY");}}
    public record Route(String id,String from,String to,String good,long amount,int delay){public Route{key(id);key(from);key(to);key(good);if(from.equals(to)||amount<1||amount>1000000||delay<1||delay>1000)throw new IllegalArgumentException("ECON_ROUTE");}}
    public record Event(String id,String kind,String target,int factor,int duration){public Event{key(id);key(target);if(!Set.of("PRODUCTION","DEMAND","ROUTE").contains(kind)||factor<0||factor>30000||duration<1||duration>100000)throw new IllegalArgumentException("ECON_EVENT");}}
    public record Policy(int spread,int smoothing,int maxStep,int impact,int minimum,int maximum){public Policy{if(spread<1||spread>5000||smoothing<1||smoothing>10000||maxStep<1||maxStep>5000||impact<0||impact>10000||minimum<1||minimum>10000||maximum<10000||maximum>100000)throw new IllegalArgumentException("ECON_PRICE_POLICY");}}
    public EconomyContent{regions=List.copyOf(regions);goods=Map.copyOf(goods);demand=Map.copyOf(demand);facilities=List.copyOf(facilities);routes=List.copyOf(routes);events=Map.copyOf(events);Objects.requireNonNull(policy);
        if(facilities.size()>4096||routes.size()>4096||events.size()>256)throw new IllegalArgumentException("ECON_CONTENT_LIMIT");
        if(regions.isEmpty()||regions.size()>128||goods.isEmpty()||goods.size()>64||new HashSet<>(regions).size()!=regions.size()||tickMillis<100||tickMillis>86400000||!Set.of("PAUSE","CATCH_UP_CAPPED").contains(offline)||catchup<1||catchup>100||fixtureBalance<0)throw new IllegalArgumentException("ECON_CONTENT");regions.forEach(EconomyContent::key);
        var ids=new HashSet<String>();for(var f:facilities){if(!ids.add(f.id())||!regions.contains(f.region())||!goods.containsKey(f.good())||!goods.keySet().containsAll(f.inputs().keySet()))throw new IllegalArgumentException("ECON_FACILITY_REF");}ids.clear();for(var route:routes)if(!ids.add(route.id())||!regions.containsAll(List.of(route.from(),route.to()))||!goods.containsKey(route.good()))throw new IllegalArgumentException("ECON_ROUTE_REF");
        for(var row:demand.entrySet())if(!regions.contains(row.getKey().region())||!goods.containsKey(row.getKey().good())||row.getValue()<0||row.getValue()>1000000)throw new IllegalArgumentException("ECON_DEMAND_REF");for(var e:events.values()){boolean valid=switch(e.kind()){case "PRODUCTION"->facilities.stream().anyMatch(f->f.id().equals(e.target()));case "ROUTE"->routes.stream().anyMatch(r->r.id().equals(e.target()));default->regions.contains(e.target());};if(!valid)throw new IllegalArgumentException("ECON_EVENT_REF");}}
    public static void key(String key){if(key==null||!key.matches("[a-z][a-z0-9_]{0,63}"))throw new IllegalArgumentException("ECON_KEY");}
    public List<Key> cells(){var keys=new ArrayList<Key>();for(var region:regions)for(var good:new TreeSet<>(goods.keySet()))keys.add(new Key(region,good));return List.copyOf(keys);}
    public String fingerprint(){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest((regions+"|"+new TreeMap<>(goods)+"|"+new TreeMap<>(demand)+"|"+facilities.stream().map(f->f.id()+f.region()+f.good()+f.capacity()+new TreeMap<>(f.inputs())+f.efficiency()).toList()+"|"+routes+"|"+new TreeMap<>(events)+"|"+policy+"|"+tickMillis+offline+catchup).getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}
    private static String text(Properties p,String key){return Objects.requireNonNull(p.getProperty(key),"Missing "+key).trim();}private static long n(Properties p,String key){return Long.parseLong(text(p,key));}
    private static List<String> list(Properties p,String key){String value=text(p,key);return value.isBlank()?List.of():Arrays.stream(value.split(",")).map(String::trim).toList();}
    public static EconomyContent parse(Properties p){var regions=list(p,"regions");var goods=new TreeMap<String,Good>();for(String id:list(p,"goods"))if(goods.put(id,new Good(id,text(p,"good."+id+".material"),n(p,"good."+id+".base"),n(p,"good."+id+".target")))!=null)throw new IllegalArgumentException("ECON_DUPLICATE_GOOD");var demand=new TreeMap<Key,Long>();for(String region:regions)for(String good:goods.keySet())demand.put(new Key(region,good),Long.parseLong(p.getProperty("demand."+region+"."+good,"0")));
        var facilities=new ArrayList<Facility>();for(String id:list(p,"facilities")){var inputs=new TreeMap<String,Long>();String raw=p.getProperty("facility."+id+".inputs","");if(!raw.isBlank())for(String item:raw.split(",")){var pair=item.trim().split(":");if(pair.length!=2||inputs.put(pair[0],Long.parseLong(pair[1]))!=null)throw new IllegalArgumentException("ECON_INPUT");}facilities.add(new Facility(id,text(p,"facility."+id+".region"),text(p,"facility."+id+".good"),n(p,"facility."+id+".capacity"),inputs,Math.toIntExact(n(p,"facility."+id+".efficiency"))));}
        var routes=new ArrayList<Route>();for(String id:list(p,"routes"))routes.add(new Route(id,text(p,"route."+id+".from"),text(p,"route."+id+".to"),text(p,"route."+id+".good"),n(p,"route."+id+".amount"),Math.toIntExact(n(p,"route."+id+".delay"))));var events=new TreeMap<String,Event>();for(String id:list(p,"events")){var event=new Event(id,text(p,"event."+id+".kind"),text(p,"event."+id+".target"),Math.toIntExact(n(p,"event."+id+".factor")),Math.toIntExact(n(p,"event."+id+".duration")));if(events.put(id,event)!=null)throw new IllegalArgumentException("ECON_EVENT_DUPLICATE");}
        return new EconomyContent(regions,goods,demand,facilities,routes,events,new Policy(Math.toIntExact(n(p,"spread")),Math.toIntExact(n(p,"smoothing")),Math.toIntExact(n(p,"max-step")),Math.toIntExact(n(p,"impact")),Math.toIntExact(n(p,"minimum")),Math.toIntExact(n(p,"maximum"))),n(p,"tick-millis"),text(p,"offline"),Math.toIntExact(n(p,"catchup-cap")),n(p,"fixture-balance"));}
}
